for name in paths:
 p=pathlib.Path(name)
 try:
  s=p.stat();print('PATH',name,'uid',s.st_uid,'gid',s.st_gid,'mode',oct(stat.S_IMODE(s.st_mode)),'directory',p.is_dir())
 except OSError as e: print('PATH',name,type(e).__name__,e.strerror)
print('PROCESS_NAMES_ONLY')
for pid in [1,os.getppid()]:
 try:print(pid,pathlib.Path(f'/proc/{pid}/comm').read_text().strip())
