sudo docker exec -i hermes-telegram-gateway-1 python3 - <<'PY'
import os
import subprocess
from pathlib import Path

interpreters = set()

for proc in Path("/proc").iterdir():
    if not proc.name.isdigit():
        continue
    try:
        exe = os.readlink(proc / "exe")
        if "python" not in Path(exe).name.lower():
            continue

        raw = (proc / "cmdline").read_bytes()
        args = [
            x.decode(errors="replace")
            for x in raw.split(b"\0") if x
        ]

        if not any("hermes" in x.lower() or "gateway" in x.lower()
                   for x in args):
            continue

        print("PROCESS_PID:", proc.name)
        print("PROCESS_EXECUTABLE:", exe)

        candidate = Path(args[0]) if args else Path(exe)
        if not candidate.is_absolute():
            candidate = Path(exe)

        if candidate.is_file():
            interpreters.add(str(candidate))

        try:
            env = (proc / "environ").read_bytes().split(b"\0")
            for item in env:
                if item.startswith(b"VIRTUAL_ENV="):
                    venv = Path(os.fsdecode(item.split(b"=", 1)[1]))
                    python = venv / "bin/python"
                    print("PROCESS_VIRTUAL_ENV:", venv)
                    if python.is_file():
                        interpreters.add(str(python))
        except OSError as e:
            print("PROCESS_ENV_ERROR:", type(e).__name__)
    except OSError:
        continue

probe = """
import sys, importlib.util
print('PYTHON:', sys.executable)
for name in ['yaml', 'faster_whisper', 'whisper', 'openai']:
    try:
        print('MODULE', name, importlib.util.find_spec(name) is not None)
    except Exception as e:
        print('MODULE_ERROR', name, type(e).__name__)
"""

if not interpreters:
    print("GATEWAY_PYTHON_NOT_IDENTIFIED")
else:
    for python in sorted(interpreters):
        print("CHECKING:", python)
        try:
            result = subprocess.run(
                [python, "-c", probe],
                capture_output=True, text=True, timeout=20
            )
            print(result.stdout, end="")
            print("EXIT_CODE:", result.returncode)
            if result.stderr:
                print("STDERR_PRESENT: True")
        except Exception as e:
            print("PROBE_ERROR:", type(e).__name__)
PY

