import re
from pathlib import Path

p = Path("/var/lib/hermes/config.yaml")
print("CONFIG:", p)
section = None
found = set()

try:
    for line in p.read_text().splitlines():
        if not line.strip() or line.lstrip().startswith("#"):
            continue
        if not line[0].isspace():
            m = re.match(r"^(stt|tts):\s*(?:#.*)?$", line)
            section = m.group(1) if m else None
            if section:
                found.add(section)
                print(section + "_SECTION: present")
            continue
        if section:
            m = re.match(r"^ {2}(enabled|provider):\s*(.*?)\s*$", line)
            if m:
                field, value = m.groups()
                value = value.split("#", 1)[0].strip().strip("'\"")
                if re.fullmatch(r"[A-Za-z0-9_-]{1,40}", value):
                    print(section + "." + field + ":", value)
                else:
                    print(section + "." + field + ": present; value omitted")
    for name in ["stt", "tts"]:
        if name not in found:
            print(name + "_SECTION: not identified")
except OSError as e:
    print("CONFIG_ERROR:", type(e).__name__)

try:
    entries = Path("/proc/7/environ").read_bytes().split(b"\0")
    env = dict(x.split(b"=", 1) for x in entries if b"=" in x)
    print("GATEWAY_ENV_PRESENCE_ONLY:")
    for name in [
        "OPENAI_API_KEY", "GROQ_API_KEY", "MISTRAL_API_KEY",
        "ELEVENLABS_API_KEY", "DEEPINFRA_API_KEY",
        "HERMES_LOCAL_STT_COMMAND", "VOICE_TOOLS_OPENAI_BASE_URL",
        "VOICE_TOOLS_OPENAI_API_KEY"
    ]:
        print(name + "_PRESENT:", bool(env.get(name.encode())))
except OSError as e:
    print("PROCESS_ENV_ERROR:", type(e).__name__)
