    for node in ast.walk(tree):
        if isinstance(node, ast.Constant) and isinstance(node.value, str):
            value = node.value
            if (value.isupper()
                and len(value) < 100
                and any(word in value
                        for word in ["STT", "WHISPER", "API_KEY", "VOICE_TOOLS"])):
                names.add(value)
    print("CREDENTIAL_OR_SETTING_NAMES_ONLY:")
    for name in sorted(names):
        print(name)

if not found:
    print("TRANSCRIPTION_SOURCE_NOT_FOUND_AT_CHECKED_PATHS")
