import os
import sys
import inspect
import logging
from pathlib import Path

p = Path("/proc/7")
args = (p / "cmdline").read_bytes().split(b"\0")
if not any(b"hermes" in x.lower() or b"gateway" in x.lower()
           for x in args[1:]):
    raise SystemExit("STOP: PID 7 is not identified as gateway")

env = {}
for item in (p / "environ").read_bytes().split(b"\0"):
    if b"=" in item:
        k, v = item.split(b"=", 1)
        env[os.fsdecode(k)] = os.fsdecode(v)
os.environ.clear()
os.environ.update(env)
print("GATEWAY_STARTUP_ENV: copied; values not printed", flush=True)

class Blocked(RuntimeError):
    pass

def guard(event, args):
    if event.startswith("socket.") or event in {
        "subprocess.Popen", "os.system", "os.exec", "os.posix_spawn",
        "os.remove", "os.rename", "os.mkdir", "os.rmdir",
        "os.chmod", "os.chown", "os.truncate",
        "os.link", "os.symlink", "os.utime"
    }:
        raise Blocked(event)
    if event == "open":
        _, mode, flags = args
        if (isinstance(mode, str) and any(x in mode for x in "wax+")) or (
            isinstance(flags, int) and flags & (
                os.O_WRONLY | os.O_RDWR | os.O_CREAT |
                os.O_TRUNC | os.O_APPEND
            )
        ):
            raise Blocked("file write")

logging.disable(logging.CRITICAL)
sys.addaudithook(guard)

try:
    from tools import transcription_tools as stt
    print("=== INSTALLED CONFIG LOADER ===")
    print(inspect.getsource(stt._load_stt_config))
