sudo docker exec -i hermes-telegram-gateway-1 /opt/hermes/.venv/bin/python -B - <<'PY'
import re
from pathlib import Path

p = Path("/var/lib/hermes/config.yaml")
allowed = {
    "auto", "default", "openai-native", "firecrawl", "searxng",
    "brave", "brave-free", "ddgs", "tavily", "perplexity",
    "keenable", "exa", "parallel", "xai"
}
fields = {"backend", "search_backend", "extract_backend"}
found = {}
in_web = False

try:
    for line in p.read_text().splitlines():
        if not line.strip() or line.lstrip().startswith("#"):
            continue
        if not line[0].isspace():
            in_web = bool(re.fullmatch(r"web:\s*(?:#.*)?", line))
            continue
        if in_web:
            m = re.fullmatch(
                r" {2}(backend|search_backend|extract_backend):\s*(.*?)\s*",
                line
            )
            if m:
                key, raw = m.groups()
                value = raw.split("#", 1)[0].strip().strip("'\"")
                found[key] = (
                    value if value in allowed
                    else "empty/null" if value in {"", "null", "~"}
                    else "nonstandard value; withheld"
                )
    print("SOURCE:", p)
    print("MODE: literal two-space YAML fields; not effective merged config")
    for key in sorted(fields):
        print("web." + key + ":",
              found.get(key, "not identified by this restricted reader"))
except OSError as e:
    print("READ_ERROR:", type(e).__name__)
PY

