import os
import sys
import ast
from pathlib import Path

print("PYTHON:", sys.version.split()[0])
print("CPU_AFFINITY_COUNT:", len(os.sched_getaffinity(0)))

for name in ["cpu.max", "memory.max", "memory.current"]:
    p = Path("/sys/fs/cgroup") / name
    if p.is_file():
        print(name + ":", p.read_text().strip())

p = Path("/opt/hermes/pyproject.toml")
if p.is_file():
    for number, line in enumerate(p.read_text().splitlines(), 1):
        if any(word in line.lower() for word in
               ["faster-whisper", "ctranslate2", "onnxruntime"]):
            print("DEPENDENCY", number, line)

p = Path("/opt/hermes/tools/transcription_local.py")
if p.is_file():
    text = p.read_text()
    lines = text.splitlines()
    for node in ast.parse(text).body:
        if isinstance(node, ast.FunctionDef):
            if node.name == "_try_lazy_install_stt":
                print("=== INSTALLED STT INSTALL ROUTINE ===")
                for i in range(node.lineno - 1, node.end_lineno):
                    print(str(i + 1) + ": " + lines[i])
