from pathlib import Path

markers = (
    "/srv/hermes-agent",
    "compose.telegram",
    "hermes-telegram-gateway",
)
files = set()

for directory in (
    "/etc/systemd/system",
    "/usr/lib/systemd/system",
    "/etc/cron.d",
):
    root = Path(directory)
    if root.is_dir():
        for p in root.rglob("*"):
            if p.is_file() and (
                p.suffix in {".service", ".timer", ".conf"}
                or directory == "/etc/cron.d"
            ):
                files.add(p)

crontab = Path("/etc/crontab")
if crontab.is_file():
    files.add(crontab)

project = Path("/srv/hermes-agent")
if project.is_dir():
    files.update(p for p in project.glob("*.sh") if p.is_file())

found = []
errors = []

for p in sorted(files):
    try:
        text = p.read_text(encoding="utf-8", errors="replace")
        if any(marker in text for marker in markers):
            found.append(str(p))
    except OSError:
        errors.append(str(p))

print("PROJECT_REFERENCES:")
print("\n".join(found) if found else "NONE_IN_CHECKED_FILES")
print("UNREADABLE_FILES:")
print("\n".join(errors) if errors else "NONE")
