import os
import shutil
import importlib.util
from pathlib import Path

print("=== Компоненты ===")
for name in ("ffmpeg", "ffprobe"):
    print(f"{name}: {'есть' if shutil.which(name) else 'не найден'}")

for name in ("edge_tts", "openai", "elevenlabs", "piper", "yaml"):
    try:
        found = importlib.util.find_spec(name) is not None
    except (ImportError, ValueError):
        found = False
    print(f"{name}: {'есть' if found else 'не найден'}")

print("\n=== Конфигурация TTS — без секретов ===")
home = os.environ.get("HERMES_HOME")
candidates = []
if home:
    candidates.append(Path(home) / "config.yaml")
candidates.append(Path.home() / ".hermes" / "config.yaml")

seen = set()
found_config = False
for path in candidates:
    if path in seen:
        continue
    seen.add(path)
    if not path.is_file():
        continue
    found_config = True
    print("Кандидат config.yaml: найден")
    try:
        import yaml
        data = yaml.safe_load(path.read_text()) or {}
        if not isinstance(data, dict):
            print("Структура конфига: неожиданная")
            continue
        tts = data.get("tts")
        print("Секция tts:", "есть" if isinstance(tts, dict) else "не задана")
        if isinstance(tts, dict):
            provider = tts.get("provider")
            known = {
                "edge", "openai", "elevenlabs", "piper",
                "kokoro", "kitten", "kittentts", "mistral",
                "gemini", "fish", "fish_audio"
            }
            if provider is None:
                print("tts.provider: явно не задан")
            elif isinstance(provider, str) and provider in known:
                print("tts.provider:", provider)
            else:
                print("tts.provider: задан; нестандартное значение скрыто")
    except Exception as exc:
        print("Не удалось прочитать конфиг; тип ошибки:", type(exc).__name__)

if not found_config:
    print("В проверенных стандартных расположениях конфиг не найден.")
    print("Это не доказывает отсутствие конфига в другом месте.")
