sudo docker exec -i hermes-telegram-gateway-1 python -B - <<'PY'
import os
import re
from pathlib import Path

paths = []
if os.environ.get("HERMES_HOME"):
    paths.append(Path(os.environ["HERMES_HOME"]) / "config.yaml")
paths.append(Path.home() / ".hermes" / "config.yaml")

known = {
    "edge", "elevenlabs", "openai", "minimax", "mistral",
    "gemini", "xai", "deepinfra", "neutts", "kittentts",
    "piper", "nous", "kokoro"
}

for path in dict.fromkeys(paths):
    if not path.is_file():
        continue
    print("=== Проверка найденного config.yaml ===")
    lines = path.read_text().splitlines()
    inside = False
    found_section = False
    found_provider = False
    for line in lines:
        if re.match(r"^tts:\s*(?:#.*)?$", line):
            inside = found_section = True
            continue
        if inside and line.strip() and not line.lstrip().startswith("#"):
            if not line[0].isspace():
                break
            match = re.fullmatch(
                r"""\s+provider:\s*["']?([a-zA-Z0-9_-]+)["']?\s*(?:#.*)?""",
                line
            )
            if match:
                value = match.group(1)
                print("Провайдер:", value if value in known else "нестандартный — скрыт")
                found_provider = True
    print("Отдельная секция tts:", "найдена" if found_section else "не обнаружена")
    if not found_provider:
        print("Провайдер этой текстовой проверкой не определён.")
PY

