    if not p.name.isdigit():
        continue
    try:
        args = (p / "cmdline").read_bytes().split(b"\0")
        if target in args and args and b"python" in args[0]:
            active.append(p.name)
    except OSError:
        pass

print("ACTIVE_SETUP_PIDS:", ",".join(active) if active else "NONE")
